head.script:
scwin.onpageload = function () {
    let arr = [
        { "name" : "Row 0", "c_text" : "10", "c_area" : "10", "c_area_fmt" : "10" },
        { "name" : "Row 1", "c_text" : "20", "c_area" : "20", "c_area_fmt" : "20" }
    ];
    dlt_a.setJSON(arr);
};

// Row 0 의 각 Column DataList 값 / 셀 표시값 출력
scwin.btn_check_onclick = function (e) {
    let cols = [["text (대조)", "c_text"], ["textarea", "c_area"], ["textarea + #,###", "c_area_fmt"]];
    for (let i = 0; i < cols.length; i++) {
        let colId = cols[i][1];
        let val = dlt_a.getCellData(0, colId);
        scwin.setReturnValue(cols[i][0] + " : DataList 값 " + String(val) + " (" + typeof val + ") / 셀 표시값 " + scwin.getCellText(grd_a, 0, colId));
    }
};

// 화면에 표시된 셀 텍스트
scwin.getCellText = function (grd, rowIndex, colId) {
    let el = document.getElementById(grd.id + "_cell_" + rowIndex + "_" + grd.getColumnIndex(colId));
    return el ? el.innerText.replace(/\n/g, " ").trim() : "(셀 없음)";
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
